package com.sibcraft.creeperborn.client;
import java.util.*;
import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraft.client.model.geom.*;
import net.minecraft.client.model.geom.builders.*;
import net.minecraft.client.renderer.SubmitNodeCollector;
import net.minecraft.client.renderer.entity.state.AvatarRenderState;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.client.renderer.rendertype.RenderTypes;
import net.minecraft.resources.Identifier;
import org.joml.Quaternionf;
/** Flame silhouettes, arm-mounted fire lances and the broad golden Buddha with pressure-wave rings. */
public final class SolarRenderer {
 private static Identifier tex(String name){return Identifier.withDefaultNamespace("textures/block/"+name+".png");}
 private static final Identifier ORANGE=tex("orange_concrete"),RED=tex("red_concrete"),YELLOW=tex("yellow_concrete"),WHITE=tex("white_concrete"),GOLD=tex("gold_block"),BLACK=tex("black_concrete"),GREEN=tex("lime_concrete");
 private static void box(PartDefinition r,String n,float x,float y,float z,float w,float h,float d){r.addOrReplaceChild(n,CubeListBuilder.create().texOffs(0,0).addBox(x,y,z,w,h,d),PartPose.ZERO);}
 private static ModelPart bake(MeshDefinition m){return LayerDefinition.create(m,16,16).bakeRoot();}
 private static final ModelPart BALL=ball(),FIST=fist(),PALM=palm(),RING=ring(),SPEAR=spear(),TIP=spearTip(),BUDDHA=buddha(),FACE=face(),FLAME=flameBody();
 private static ModelPart ball(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"middle",-6,-5,-5,12,10,10);box(r,"top",-4,-7,-4,8,14,8);box(r,"sides",-7,-3,-3,14,6,6);return bake(m);}
 private static ModelPart fist(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"palm",-5,-4,0,10,8,8);for(int i=0;i<4;i++)box(r,"knuckle"+i,-4.8f+i*2.4f,-3.5f,7,2,7,3);box(r,"thumb",4,-5,2,3,5,5);box(r,"forearm",-3,-3,-9,6,6,10);return bake(m);}
 private static ModelPart palm(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"palm",-5,-5,-1,10,10,3);for(int i=0;i<4;i++)box(r,"finger"+i,-5+i*2.6f,4,-1,2.2f,6+i%2*2,3);box(r,"thumb",5,-4,-1,3,7,3);return bake(m);}
 private static ModelPart ring(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();for(int i=0;i<48;i++){double a=i*Math.PI/24,b=(i+1)*Math.PI/24;float x=(float)Math.cos(a)*8,y=(float)Math.sin(a)*8,dx=(float)(Math.cos(b)-Math.cos(a))*8,dy=(float)(Math.sin(b)-Math.sin(a))*8;var q=r.addOrReplaceChild("arc"+i,CubeListBuilder.create(),PartPose.offsetAndRotation(x,y,0,0,0,(float)Math.atan2(dy,dx)));box(q,"line",0,-.12f,-.08f,(float)Math.sqrt(dx*dx+dy*dy)+.1f,.24f,.16f);}return bake(m);}
 private static ModelPart spear(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"flame_shaft",-1.8f,-1.8f,0,3.6f,3.6f,16);return bake(m);}
 private static ModelPart spearTip(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();float[] widths={7,14,20,15,9,3};for(int i=0;i<widths.length;i++){float w=widths[i];box(r,"leaf"+i,-w/2,-w*.2f,i*5.8f,w,w*.4f,6);}return bake(m);}
 private static ModelPart flameBody(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"torso",-4,10,-2,8,12,4);box(r,"head",-4,22,-4,8,8,8);for(int side:new int[]{-1,1}){box(r,"arm"+side,side*5-1.5f,10,-1.5f,3,12,3);box(r,"leg"+side,side*2-1.7f,0,-1.7f,3.4f,11,3.4f);}return bake(m);}
 private static ModelPart buddha(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"belly",-22,22,-12,44,35,24);box(r,"chest",-25,48,-11,50,20,22);box(r,"neck",-8,65,-7,16,8,14);box(r,"head",-14,72,-11,28,27,22);box(r,"robe",-24,21,-12.5f,48,10,25);for(int side:new int[]{-1,1}){box(r,"ear"+side,side*15-2,70,-3,4,21,5);box(r,"leg"+side,side*11-8,0,-7,16,25,14);box(r,"foot"+side,side*11-9,0,-8,18,6,23);var arm=r.addOrReplaceChild("arm"+side,CubeListBuilder.create(),PartPose.offset(side*29,64,0));box(arm,"upper",-7,-21,-7,14,24,14);box(arm,"forearm",-8,-41,-8,16,23,16);box(arm,"palm",-9,-48,-7,18,14,14);for(int i=0;i<4;i++)box(arm,"finger"+i,-8+i*4.5f,-56,-7,3.5f,10,12);}for(int row=0;row<4;row++)for(int col=0;col<6;col++)box(r,"curl"+row+"_"+col,-14+col*4.6f,91+row*2.4f,-11.5f,4,3,3);box(r,"crown",-6,99,-5,12,6,10);return bake(m);}
 private static ModelPart face(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();for(int side:new int[]{-1,1})box(r,"eye"+side,side*6-3,85,11.2f,6,1.2f,.3f);box(r,"nose",-2,79,11,4,7,3);box(r,"mouth",-5,76,11.2f,10,1,.3f);box(r,"dot",-1,91,11.2f,2,2,.3f);return bake(m);}
 private static void draw(ModelPart model,Identifier tex,PoseStack p,SubmitNodeCollector n,boolean glow){n.submitModelPart(model,p,glow?RenderTypes.eyes(tex):RenderTypes.entityTranslucent(tex),0xF000F0,OverlayTexture.NO_OVERLAY,null);}
 private static void fire(PoseStack p,SubmitNodeCollector n,float age,float size){p.pushPose();p.scale(size,size,size);draw(BALL,RED,p,n,true);p.scale(.86f,.86f,.86f);draw(BALL,ORANGE,p,n,true);p.scale(.72f,.72f,.72f);draw(BALL,YELLOW,p,n,true);p.scale(.5f,.5f,.5f);draw(BALL,WHITE,p,n,true);p.popPose();for(int i=0;i<7;i++){p.pushPose();double a=age*.11+i*Math.PI*2/7;p.translate(Math.cos(a)*size*.4,Math.sin(a)*size*.4,-size*.25);p.rotate(new Quaternionf().rotationZ((float)a));p.scale(size*.12f,size*.35f,size*.12f);draw(BALL,ORANGE,p,n,true);p.popPose();}}
 public static float spearThrust(float progress){return .9f*(float)Math.sin(Math.PI*Math.max(0,Math.min(1,progress)));}
 private static float swingProgress(AvatarRenderState state){var c=net.minecraft.client.Minecraft.getInstance();return c.level!=null&&c.level.getEntity(state.id) instanceof net.minecraft.world.entity.LivingEntity e?e.getSwingAnimation(state.ageInTicks-(float)Math.floor(state.ageInTicks)):0;}
 private static void lance(PoseStack p,SubmitNodeCollector n,float age,float length){float shaft=length-2.15f;p.pushPose();p.scale(1,1,shaft);draw(SPEAR,ORANGE,p,n,true);p.scale(.5f,.5f,1);draw(SPEAR,YELLOW,p,n,true);p.popPose();p.pushPose();p.translate(0,0,shaft);float pulse=1+(float)Math.sin(age*.3)*.08f;p.scale(pulse,pulse,1);draw(TIP,RED,p,n,true);p.scale(.84f,.84f,.98f);draw(TIP,ORANGE,p,n,true);p.scale(.66f,.66f,.98f);draw(TIP,YELLOW,p,n,true);p.popPose();for(int i=0;i<14;i++){p.pushPose();float z=(i+.5f)*shaft/14;double a=age*.16+i*.9;p.translate(Math.cos(a)*.15,Math.sin(a)*.15,z);p.rotate(new Quaternionf().rotationZ((float)a));p.scale(.28f,.45f,.6f);draw(TIP,i%3==0?RED:ORANGE,p,n,true);p.popPose();}}
 public static void effect(int kind,float age,PoseStack p,SubmitNodeCollector n){p.pushPose();if(kind==19){draw(FIST,ORANGE,p,n,true);p.pushPose();p.scale(.75f,.75f,.75f);draw(FIST,YELLOW,p,n,true);p.popPose();for(int i=0;i<7;i++){p.pushPose();p.translate(Math.sin(age*.2+i)*.15,Math.cos(age*.2+i)*.15,-i*.3);fire(p,n,age,.6f-i*.06f);p.popPose();}}
  else if(kind==20){fire(p,n,age,.35f);p.translate(0,0,-.8);p.scale(.2f,.2f,1.2f);draw(SPEAR,ORANGE,p,n,true);}
  else if(kind==21){for(int i=0;i<12;i++){p.pushPose();double a=age*.08+i*Math.PI/6;p.translate(Math.cos(a)*1.15,Math.sin(a*2)*.8,Math.sin(a)*1.15);p.scale(.25f,.25f,.25f);draw(BALL,i%2==0?GREEN:YELLOW,p,n,true);p.popPose();}}
  else if(kind==22){fire(p,n,age,Math.min(3,.3f+age*.12f));}
  else if(kind==23||kind==25){for(int i=0;i<3;i++){p.pushPose();float size=1+i*.35f;p.translate(0,0,-i*.3);p.scale(size,size,size);draw(RING,i==1?WHITE:YELLOW,p,n,true);p.popPose();}if(kind==25)draw(PALM,GOLD,p,n,true);}
  else if(kind==24){p.rotate(new Quaternionf().rotationX((float)Math.PI/2));float size=Math.min(1,age/16);for(int i=0;i<3;i++){p.pushPose();p.scale(size-i*.1f,size-i*.1f,1);draw(RING,i==1?WHITE:YELLOW,p,n,true);p.popPose();}}
  else if(kind==27){fire(p,n,age,Math.max(.1f,1-age/20));}p.popPose();}
 public static void avatar(AvatarRenderState state,PoseStack p,SubmitNodeCollector n,int flags,boolean overlay){boolean flame=(flags&2048)!=0,form=(flags&4)!=0;float age=state.ageInTicks;p.pushPose();p.rotate(new Quaternionf().rotationY((float)Math.toRadians(-state.bodyRot)));if(form&&!overlay){if(flame){draw(FLAME,ORANGE,p,n,true);p.pushPose();p.scale(.88f,.98f,.88f);draw(FLAME,YELLOW,p,n,true);p.popPose();for(int i=0;i<8;i++){p.pushPose();double a=age*.08+i*Math.PI/4;p.translate(Math.cos(a)*.35,.2+i*.22,Math.sin(a)*.35);fire(p,n,age,.2f);p.popPose();}}else{for(int side:new int[]{-1,1}){boolean thrust=(flags&(side==-1?16384:32768))!=0;BUDDHA.getChild("arm"+side).xRot=thrust?-1.2f:0;}draw(BUDDHA,GOLD,p,n,false);draw(FACE,BLACK,p,n,false);}}if(flame&&(flags&8192)!=0){int tier=(flags>>8)&3;float length=com.sibcraft.creeperborn.CelestialPowers.spearLength(tier);var c=net.minecraft.client.Minecraft.getInstance();var entity=c.level==null?null:c.level.getEntity(state.id);float pitch=entity==null?0:entity.getXRot(),yaw=entity==null?state.bodyRot:entity.getYRot();for(int side:new int[]{-1,1}){p.pushPose();p.rotate(new Quaternionf().rotationY((float)Math.toRadians(state.bodyRot-yaw)));p.translate(side*.45,1.25,.3);p.rotate(new Quaternionf().rotationX((float)Math.toRadians(pitch)));if((flags&(side==-1?16384:32768))!=0)p.translate(0,0,spearThrust(swingProgress(state)));else p.rotate(new Quaternionf().rotationY(side*.04f));lance(p,n,age,length);p.popPose();}}p.popPose();}
 public static void hands(PoseStack p,SubmitNodeCollector n,int flags,float age){if((flags&8192)==0)return;var c=net.minecraft.client.Minecraft.getInstance();float progress=c.player==null?0:c.player.getSwingAnimation(age-(float)Math.floor(age));for(int side:new int[]{-1,1}){p.pushPose();p.translate(side*.4,-.28,-.65);p.rotate(new Quaternionf().rotationY((float)Math.PI));if((flags&(side==-1?16384:32768))!=0)p.translate(0,0,spearThrust(progress));else p.rotate(new Quaternionf().rotationY(-side*.04f));lance(p,n,age,com.sibcraft.creeperborn.CelestialPowers.spearLength((flags>>8)&3));p.popPose();}}
 public static List<Identifier> textures(){return List.of(ORANGE,RED,YELLOW,WHITE,GOLD,BLACK,GREEN);}
 public static void validate(){BUDDHA.getChild("arm-1").getChild("palm");TIP.getChild("leaf2");SPEAR.getChild("flame_shaft");}
}
